    func testWebPruningStillSeparatesOppositeLegs() throws {
        let original = PlannedRoutePresentationTests.roundTrip
        var cleaned = original
        for i in cleaned.indices { cleaned[i].points = try PlannedRoutePresentation.points(original[i].points) }
        let separated = try RouteOverlapPresentation.separate(cleaned)
        for i in cleaned.indices {
            XCTAssertNotEqual(separated[i].points, cleaned[i].points)
            XCTAssertEqual(separated[i].points.first, cleaned[i].points.first)
            XCTAssertEqual(separated[i].points.last, cleaned[i].points.last)
            XCTAssertEqual(separated[i].unseparatedPoints, cleaned[i].points)
        }
        let repeated = try RouteOverlapPresentation.separate(separated)
        XCTAssertEqual(repeated.map(\.points), separated.map(\.points))
    }
